package mx.transcriptor.studio;
import java.io.*;import java.util.*;
public final class WavFiles {
 static int le(RandomAccessFile r)throws IOException{return Integer.reverseBytes(r.readInt());}
 static void word(OutputStream o,int n)throws IOException{for(int i=0;i<4;i++)o.write(n>>>(8*i));}
 static final class Piece{File file;byte[] format;long offset;int size;}
 static Piece inspect(File f)throws IOException{try(RandomAccessFile r=new RandomAccessFile(f,"r")){if(r.readInt()!=0x52494646)throw new IOException("El motor no entregó WAV RIFF");le(r);if(r.readInt()!=0x57415645)throw new IOException("WAV inválido");Piece p=new Piece();p.file=f;while(r.getFilePointer()+8<=r.length()){int type=r.readInt(),size=le(r);long start=r.getFilePointer();if(size<0||start+size>r.length())throw new IOException("Audio incompleto");if(type==0x666d7420){if(size>1024)throw new IOException("Formato WAV inválido");p.format=new byte[size];r.readFully(p.format);}if(type==0x64617461){p.offset=start;p.size=size;}r.seek(start+size+(size&1));}if(p.format==null||p.size==0)throw new IOException("WAV sin audio");return p;}}
 public static void join(List<File> files,File out,int pauseMs)throws IOException{if(files.isEmpty())throw new IOException("Sin segmentos");List<Piece> ps=new ArrayList<>();long total=0;byte[] fmt=null;for(File f:files){Piece p=inspect(f);if(fmt!=null&&!Arrays.equals(fmt,p.format))throw new IOException("El motor cambió el formato de audio");fmt=p.format;ps.add(p);total+=p.size;}int align=(fmt[12]&255)|((fmt[13]&255)<<8);long byteRate=(fmt[8]&255L)|((fmt[9]&255L)<<8)|((fmt[10]&255L)<<16)|((fmt[11]&255L)<<24);if(align==0)throw new IOException("WAV inválido");int silence=(int)(byteRate*pauseMs/1000);silence-=silence%align;total+=(long)silence*(ps.size()-1);if(total>500*1024*1024L)throw new IOException("Audio final demasiado grande");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(out))){o.write("RIFF".getBytes("US-ASCII"));word(o,(int)(4+8+fmt.length+(fmt.length&1)+8+total+(total&1)));o.write("WAVEfmt ".getBytes("US-ASCII"));word(o,fmt.length);o.write(fmt);if((fmt.length&1)!=0)o.write(0);o.write("data".getBytes("US-ASCII"));word(o,(int)total);byte[] buf=new byte[8192];int bits=(fmt[14]&255)|((fmt[15]&255)<<8);byte[] zero=new byte[8192];if(bits==8)Arrays.fill(zero,(byte)128);for(int i=0;i<ps.size();i++){Piece p=ps.get(i);try(RandomAccessFile r=new RandomAccessFile(p.file,"r")){r.seek(p.offset);int left=p.size;while(left>0){int n=r.read(buf,0,Math.min(left,buf.length));if(n<0)throw new EOFException();o.write(buf,0,n);left-=n;}}if(i+1<ps.size()){int left=silence;while(left>0){int n=Math.min(left,zero.length);o.write(zero,0,n);left-=n;}}}if((total&1)!=0)o.write(0);}}
}
